# Bundle classification backfill, 2026-09-22. Evidence per listing was read from
# the gym's own page (tmp/bundles/pages/ holds the fetched copies; batch-*.json
# the per-listing quotes). Records what each bundle's classes are split by and
# the fact that distinguishes each class; renames classes to the naming rule in
# docs/operations.md, carrying every session's label with it. Sessions are only
# rewritten where a class is renamed; nothing else about a listing changes.
alias ClimbOntario.Catalogue
alias ClimbOntario.Catalogue.Import

plan = Jason.decode!(Base.decode64!(""))

results =
  Enum.map(plan, fn %{"id" => id, "bundled_by" => by, "classes" => classes} ->
    l = Catalogue.get_listing(id)
    rename = Map.new(classes, &{&1["old"], &1["name"]})
    renamed? = Enum.any?(classes, &(&1["old"] != &1["name"]))

    facts =
      classes
      |> Enum.filter(&(&1["ages"] || &1["level"] || &1["format"]))
      |> Enum.map(&%{name: &1["name"], ages: &1["ages"], level: &1["level"], format: &1["format"]})

    attrs = %{
      id: id,
      cohorts: Enum.map(classes, & &1["name"]),
      bundled_by: by,
      classes: facts,
      complete_cohorts: Enum.map(l.complete_cohorts, &Map.get(rename, &1, &1))
    }

    sessions =
      if renamed?,
        do:
          Enum.map(l.occurrences, fn o ->
            %{
              date: o.date, cohort: Map.get(rename, o.cohort, o.cohort),
              start_time: o.start_time, end_time: o.end_time, timezone: o.timezone,
              location_kind: o.location_kind, venue_id: o.venue_id,
              offsite_name: o.offsite_name, offsite_address: o.offsite_address,
              offsite_city: o.offsite_city, offsite_lat: o.offsite_lat, offsite_lng: o.offsite_lng
            }
          end),
        else: :preserve

    case Import.put_listing(attrs, sessions) do
      {:ok, updated} ->
        bad = Enum.reject(updated.occurrences, &(is_nil(&1.cohort) or &1.cohort in updated.cohorts))
        {id, :ok, length(updated.occurrences), length(l.occurrences), length(bad)}

      {:error, cs} ->
        {id, :error, inspect(cs.errors), nil, nil}
    end
  end)

for {id, :error, err, _, _} <- results, do: IO.puts("FAIL #{id}: #{err}")
ok = Enum.filter(results, &(elem(&1, 1) == :ok))
IO.puts("applied #{length(ok)} of #{length(results)}; session count changes: #{inspect(for {id, :ok, a, b, _} <- ok, a != b, do: {id, b, a})}; orphan labels: #{Enum.sum(for {_, :ok, _, _, n} <- ok, do: n)}")
